SELECT DISTINCTROW [Intervallo date per le stampe].Codice, Count([Intervallo date per le stampe].[Commessa di taglio]) AS [ConteggiodiCommessa di taglio]
FROM [Intervallo date per le stampe]
WHERE (([Intervallo date per le stampe].[NC 01]<>0)) OR (([Intervallo date per le stampe].[NC 02]<>0)) OR (([Intervallo date per le stampe].[NC 03]<>0)) OR (([Intervallo date per le stampe].[NC 04]<>0)) OR (([Intervallo date per le stampe].[NC 05]<>0)) OR (([Intervallo date per le stampe].[NC 06]<>0)) OR (([Intervallo date per le stampe].[NC 07]<>0)) OR (([Intervallo date per le stampe].[NC 08]<>0)) OR (([Intervallo date per le stampe].[NC 09]<>0)) OR (([Intervallo date per le stampe].[NC 10]<>0)) OR (([Intervallo date per le stampe].[NC 11]<>0)) OR (([Intervallo date per le stampe].[NC 12]<>0)) OR (([Intervallo date per le stampe].[NC 13]<>0)) OR (([Intervallo date per le stampe].[NC 14]<>0)) OR (([Intervallo date per le stampe].[NC 15]<>0)) OR (([Intervallo date per le stampe].[NC 16]<>0)) OR (([Intervallo date per le stampe].[NC 17]<>0))
GROUP BY [Intervallo date per le stampe].Codice;
